SELECT order_id FROM ret_order_guard
WHERE tenant_id=#{tenantId} AND order_id=#{orderId}
FOR UPDATE

SELECT request_sha256 AS requestSha256,aggregate_id AS aggregateId
FROM ret_idempotency
WHERE tenant_id=#{tenantId} AND command_type=#{commandType} AND idempotency_key=#{idempotencyKey}

SELECT  FROM ret_return
WHERE tenant_id=#{tenantId} AND return_id=#{returnId}
FOR UPDATE

mapper.update:
UPDATE ret_return SET status='PROMOTION_PENDING',approver_user_id=#{approverUserId},
  promotion_event_id=#{promotionEventId},record_version=record_version+1,updated_at=#{occurredAt}
WHERE tenant_id=#{tenantId} AND return_id=#{returnId} AND status='PENDING_APPROVAL'
  AND record_version=#{expectedVersion}

UPDATE ret_return SET status=#{nextStatus},gross_amount_minor=#{grossAmountMinor},
  recovered_discount_minor=#{recoveredDiscountMinor},refundable_amount_minor=#{refundableAmountMinor},
  payment_event_id=#{paymentEventId},inventory_event_id=#{inventoryEventId},
  record_version=record_version+1,updated_at=#{occurredAt}
WHERE tenant_id=#{tenantId} AND return_id=#{returnId} AND status='PROMOTION_PENDING'
  AND record_version=#{expectedVersion}

UPDATE ret_return_line SET gross_amount_minor=#{grossAmountMinor},
  recovered_discount_minor=#{recoveredDiscountMinor},refundable_amount_minor=#{refundableAmountMinor},
  cumulative_quantity=#{cumulativeQuantity},cumulative_payable_amount_minor=#{cumulativePayableAmountMinor}
WHERE tenant_id=#{tenantId} AND return_id=#{returnId} AND order_line_id=#{orderLineId}
  AND gross_amount_minor IS NULL

UPDATE ret_return SET status=#{nextStatus},inventory_event_id=COALESCE(inventory_event_id,#{inventoryEventId}),
  record_version=record_version+1,updated_at=#{occurredAt}
WHERE tenant_id=#{tenantId} AND return_id=#{returnId} AND status=#{expectedStatus}
  AND record_version=#{expectedVersion}

UPDATE ret_return SET status='COMPLETED',record_version=record_version+1,updated_at=#{occurredAt}
WHERE tenant_id=#{tenantId} AND return_id=#{returnId} AND status='INVENTORY_PENDING'
  AND record_version=#{expectedVersion}

